CREATE TABLE app_users(id BIGINT IDENTITY PRIMARY KEY,email NVARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,enabled BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE catalog_items(
id BIGINT IDENTITY PRIMARY KEY,kind VARCHAR(12) NOT NULL CHECK(kind IN ('PROPERTY','PROJECT','ARTICLE','PAGE')),slug NVARCHAR(240) NOT NULL,
title_vi NVARCHAR(500) NOT NULL,title_en NVARCHAR(500) NOT NULL,title_ru NVARCHAR(500) NOT NULL,
summary_vi NVARCHAR(2000) NOT NULL DEFAULT N'',summary_en NVARCHAR(2000) NOT NULL DEFAULT N'',summary_ru NVARCHAR(2000) NOT NULL DEFAULT N'',
body_vi NVARCHAR(MAX) NOT NULL DEFAULT N'',body_en NVARCHAR(MAX) NOT NULL DEFAULT N'',body_ru NVARCHAR(MAX) NOT NULL DEFAULT N'',cover_url NVARCHAR(1000) NOT NULL DEFAULT N'',
transaction_type VARCHAR(8) NULL CHECK(transaction_type IN ('SALE','RENT')),property_type VARCHAR(30) NULL,project_id BIGINT NULL REFERENCES catalog_items(id),
price DECIMAL(19,2) NOT NULL DEFAULT 0 CHECK(price>=0),area DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(area>=0),bedrooms INT NOT NULL DEFAULT 0 CHECK(bedrooms BETWEEN 0 AND 100),
city NVARCHAR(120) NOT NULL DEFAULT N'Quy Nhơn',direction NVARCHAR(120) NOT NULL DEFAULT N'',furniture NVARCHAR(120) NOT NULL DEFAULT N'',legal_status NVARCHAR(120) NOT NULL DEFAULT N'',position NVARCHAR(120) NOT NULL DEFAULT N'',
search_text NVARCHAR(2000) NOT NULL DEFAULT N'',data_json NVARCHAR(MAX) NOT NULL DEFAULT N'{}' CHECK(ISJSON(data_json)=1),published BIT NOT NULL DEFAULT 1,
version BIGINT NOT NULL DEFAULT 0,published_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
CONSTRAINT uq_catalog_kind_slug UNIQUE(kind,slug));
CREATE INDEX ix_catalog_listing ON catalog_items(kind,published,transaction_type,published_at DESC) INCLUDE(price,area,bedrooms,property_type,project_id,cover_url);
CREATE INDEX ix_catalog_price ON catalog_items(kind,published,price,id);
CREATE INDEX ix_catalog_project ON catalog_items(project_id,published,transaction_type);
CREATE TABLE site_settings(id INT PRIMARY KEY CHECK(id=1),data_json NVARCHAR(MAX) NOT NULL CHECK(ISJSON(data_json)=1),version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE leads(id BIGINT IDENTITY PRIMARY KEY,reference CHAR(36) NOT NULL UNIQUE,idempotency_key VARCHAR(80) NOT NULL UNIQUE,name NVARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL,email NVARCHAR(254) NOT NULL DEFAULT N'',purpose VARCHAR(20) NOT NULL CHECK(purpose IN ('BUY','RENT','CONSIGN','INQUIRY')),message NVARCHAR(4000) NOT NULL,property_slug NVARCHAR(240) NULL,status VARCHAR(12) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','CONTACTED','CLOSED')),version BIGINT NOT NULL DEFAULT 0,created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX ix_leads_status_created ON leads(status,created_at DESC);
CREATE TABLE SPRING_SESSION(PRIMARY_ID CHAR(36) NOT NULL PRIMARY KEY,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME NVARCHAR(254));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL,ATTRIBUTE_NAME NVARCHAR(200) NOT NULL,ATTRIBUTE_BYTES VARBINARY(MAX) NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
